def longest_at_centers(s):
    n = len(s)
    out = []
    for c in range(2 * n - 1):
        lo, hi = c // 2, c // 2 + c % 2
        while lo >= 0 and hi < n and s[lo] == s[hi]:
            lo, hi = lo - 1, hi + 1
        out.append(hi - lo - 1)
    return out

