static int[] longestAtCenters(String s) {
    int n = s.length();
    int[] out = new int[Math.max(0, 2 * n - 1)];
    for (int c = 0; c < 2 * n - 1; c++) {
        int lo = c / 2, hi = c / 2 + c % 2;
        while (lo >= 0 && hi < n && s.charAt(lo) == s.charAt(hi)) {
            lo--;
            hi++;
        }
        out[c] = hi - lo - 1;
    }
    return out;
}

