def longest_one_fix(s):
    n, best = len(s), 0
    for c in range(2 * n - 1):
        lo, hi = c // 2, c // 2 + c % 2
        fixes = 0
        while lo >= 0 and hi < n:
            if s[lo] != s[hi]:
                if fixes == 1:
                    break
                fixes += 1
            lo, hi = lo - 1, hi + 1
        best = max(best, hi - lo - 1)
    return best

