        int fixes = 0;
        while (lo >= 0 && hi < n) {
            if (s.charAt(lo) != s.charAt(hi)) {
                if (fixes == 1) break;
                fixes++;
            }
            lo--;
            hi++;
        }
        best = Math.max(best, hi - lo - 1);
